import os, glob, re, json

def load():
    d = os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t = open(d + '/../../sessions/' + os.path.basename(d) + '.jsonl').read().replace('\\n', '\n')
    G = {}
    for msg in t.split('\n'):
        msg = msg.strip()
        if not msg:
            continue
        if msg.startswith('Demo pair ') or msg.startswith('Test input '):
            match = re.match(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n(.+?)(?=\n|$)', msg, re.DOTALL)
            if match:
                popup_id, h, w = match.group(2), int(match.group(3)), int(match.group(4))
                grid_text = match.group(5)
                if 'Test input' not in match.group(1):
                    # This is an input or output
                    rows = grid_text.split('\n')[:h]
